import React, { useEffect, useMemo, useState } from 'react';
import { io } from 'socket.io-client';
import { useNavigate } from 'react-router-dom';
import { api, normalizeArrayPayload, badgeClass } from '../services/api';

const SOCKET_URL = 'http://localhost:5000';

function scoreBadgeClass(score) {
  const val = Number(score || 0);
  if (val >= 70) return 'badge badge-high';
  if (val >= 40) return 'badge badge-medium';
  return 'badge badge-low';
}

function formatTime(ts) {
  if (!ts) return '—';
  try {
    return new Date(ts).toLocaleString();
  } catch {
    return ts;
  }
}

function FraudAlertToast({ alert, onClose }) {
  if (!alert) return null;

  const hasCycle = Array.isArray(alert.cycle_path) && alert.cycle_path.length >= 4;

  return (
    <div
      style={{
        position: 'fixed',
        top: 88,
        right: 24,
        width: 360,
        zIndex: 1000,
        background: 'linear-gradient(180deg, rgba(20,8,8,0.98), rgba(8,3,3,0.98))',
        border: '1px solid rgba(90,255,145,0.14)',
        borderRadius: 18,
        padding: 18,
        boxShadow: '0 18px 50px rgba(0,0,0,0.55)',
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 10 }}>
        <div style={{ display: 'flex', gap: 12 }}>
          <div
            style={{
              width: 14,
              height: 14,
              borderRadius: 999,
              background: '#77ffad',
              boxShadow: '0 0 18px rgba(119,255,173,0.45)',
              marginTop: 4,
              flexShrink: 0,
            }}
          />
          <div>
            <div style={{ color: '#effff2', fontSize: 16, fontWeight: 900 }}>
              {hasCycle ? 'Circular Loop Detected' : 'Suspicious Activity'}
            </div>
            <div style={{ color: '#8eb69a', fontSize: 14, lineHeight: 1.4, marginTop: 6 }}>
              {hasCycle
                ? `Loop: ${alert.cycle_path.join(' → ')}`
                : alert.reason || 'Suspicious trade activity'}
            </div>
            <div style={{ color: '#617468', fontSize: 12, marginTop: 8 }}>
              Trade #{alert.trade_id} • Score {alert.risk_score}
            </div>
          </div>
        </div>

        <button
          onClick={onClose}
          style={{
            background: 'transparent',
            border: 0,
            color: '#789183',
            cursor: 'pointer',
            fontSize: 20,
            lineHeight: 1,
          }}
        >
          ×
        </button>
      </div>
    </div>
  );
}

function StatCard({ label, value, color }) {
  return (
    <div
      style={{
        padding: 22,
        borderRadius: 20,
        background: 'linear-gradient(180deg, rgba(8,26,17,0.92), rgba(0,0,0,0.96))',
        border: '1px solid rgba(91,255,145,0.10)',
        boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.02), 0 14px 40px rgba(0,0,0,0.35)',
        backdropFilter: 'blur(16px)',
        WebkitBackdropFilter: 'blur(16px)',
      }}
    >
      <div
        style={{
          color: '#7a9382',
          fontSize: 12,
          fontWeight: 800,
          letterSpacing: '0.08em',
          textTransform: 'uppercase',
          marginBottom: 14,
        }}
      >
        {label}
      </div>
      <div style={{ fontSize: 40, fontWeight: 900, color }}>{value}</div>
    </div>
  );
}

export default function FraudPage() {
  const navigate = useNavigate();

  const [stats, setStats] = useState({});
  const [fraudCycles, setFraudCycles] = useState([]);
  const [riskLogs, setRiskLogs] = useState([]);
  const [activeTab, setActiveTab] = useState('cycles');
  const [toast, setToast] = useState(null);

  const loadAll = async () => {
    try {
      const [statsRes, cyclesRes, logsRes] = await Promise.all([
        api.fetchStats(),
        api.fetchFraudCycles(),
        api.fetchFraudLogs(),
      ]);

      const cycles = normalizeArrayPayload(cyclesRes);
      const logs = normalizeArrayPayload(logsRes);

      setStats(statsRes || {});
      setFraudCycles(cycles);
      setRiskLogs(logs);
    } catch (error) {
      console.error('FraudPage load error:', error);
    }
  };

  useEffect(() => {
    loadAll();

    const intervalId = setInterval(loadAll, 2500);
    const socket = io(SOCKET_URL, { transports: ['websocket', 'polling'] });

    socket.on('fraud_detected', (payload) => {
      loadAll();
      if (payload?.cycle_path?.length >= 4) setToast(payload);
    });

    socket.on('fraud_alert', (payload) => {
      loadAll();
      if (payload?.cycle_path?.length >= 4) setToast(payload);
    });

    socket.on('risk_log', loadAll);
    socket.on('trade_inserted', loadAll);

    return () => {
      clearInterval(intervalId);
      socket.disconnect();
    };
  }, []);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 5000);
    return () => clearTimeout(t);
  }, [toast]);

  const abnormalCount = useMemo(
    () =>
      riskLogs.filter((r) =>
        String(r?.reason || '').toLowerCase().includes('abnormal price')
      ).length,
    [riskLogs]
  );

  return (
    <div className="page-wrap grid-bg" style={{ background: '#000000' }}>
      <FraudAlertToast alert={toast} onClose={() => setToast(null)} />

      <div className="page-container">
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            gap: 20,
            alignItems: 'flex-start',
            marginBottom: 18,
          }}
        >
          <div>
            <h1 style={{ fontSize: 28, fontWeight: 900, margin: 0, color: '#ecfff1' }}>
              Fraud <span style={{ color: '#72ffab' }}>Engine</span>
            </h1>
            <div style={{ color: '#779184', marginTop: 10, fontSize: 14 }}>
              Loops shown separately, non-loop suspicious trades shown in risk log
            </div>
          </div>

          <button
            className="btn-outline"
            onClick={() => navigate('/traders')}
            style={{
              background: 'rgba(10,30,18,0.82)',
              borderColor: 'rgba(91,255,145,0.14)',
              color: '#cbf7d7',
            }}
          >
            Traders
          </button>
        </div>

        <div className="kpi-grid" style={{ marginBottom: 18 }}>
          <StatCard
            label="Loop Groups"
            value={fraudCycles.length}
            color="#74ffad"
          />
          <StatCard
            label="Abnormal Price Logs"
            value={abnormalCount}
            color="#baff8f"
          />
          <StatCard
            label="Risk Log Entries"
            value={riskLogs.length}
            color="#97f3ba"
          />
        </div>

        <div style={{ display: 'flex', gap: 12, marginBottom: 16 }}>
          <button
            onClick={() => setActiveTab('cycles')}
            className={activeTab === 'cycles' ? 'btn-primary' : 'btn-outline'}
            style={
              activeTab === 'cycles'
                ? {
                    background: 'linear-gradient(180deg, #19462b, #0c1f14)',
                    color: '#ebfff1',
                    border: '1px solid rgba(91,255,145,0.18)',
                  }
                : {
                    background: 'rgba(10,26,17,0.9)',
                    color: '#d7efe0',
                    border: '1px solid rgba(91,255,145,0.12)',
                  }
            }
          >
            Loop Section ({fraudCycles.length})
          </button>

          <button
            onClick={() => setActiveTab('logs')}
            className={activeTab === 'logs' ? 'btn-primary' : 'btn-outline'}
            style={
              activeTab === 'logs'
                ? {
                    background: 'linear-gradient(180deg, #19462b, #0c1f14)',
                    color: '#ebfff1',
                    border: '1px solid rgba(91,255,145,0.18)',
                  }
                : {
                    background: 'rgba(10,26,17,0.9)',
                    color: '#d7efe0',
                    border: '1px solid rgba(91,255,145,0.12)',
                  }
            }
          >
            Risk Log ({riskLogs.length})
          </button>
        </div>

        {activeTab === 'cycles' ? (
          <div
            style={{
              overflow: 'hidden',
              borderRadius: 22,
              background: 'linear-gradient(180deg, rgba(8,26,17,0.92), rgba(0,0,0,0.96))',
              border: '1px solid rgba(91,255,145,0.10)',
              boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.02), 0 14px 40px rgba(0,0,0,0.35)',
            }}
          >
            <div
              style={{
                padding: '18px 20px',
                borderBottom: '1px solid rgba(255,255,255,0.05)',
              }}
            >
              <div style={{ fontSize: 18, fontWeight: 900, color: '#ebfff0' }}>
                Detected Circular Loops
              </div>
              <div style={{ color: '#71877b', fontSize: 13, marginTop: 6 }}>
                Exact loop path and trade path are shown here, not in the risk log
              </div>
            </div>

            <div className="scroll-y" style={{ maxHeight: 560 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Stock</th>
                    <th>Loop Path</th>
                    <th>Trade Path</th>
                    <th>Depth</th>
                    <th>Confidence</th>
                  </tr>
                </thead>
                <tbody>
                  {fraudCycles.map((item, idx) => (
                    <tr key={`${item.group_id || item.trade_id}-${idx}`}>
                      <td>{item.symbol || `#${item.stock_id}`}</td>
                      <td style={{ color: '#74ffad', fontWeight: 800 }}>
                        {Array.isArray(item.cycle) ? item.cycle.join(' → ') : '—'}
                      </td>
                      <td style={{ color: '#93a79a' }}>
                        {Array.isArray(item.trade_path) ? item.trade_path.join(' → ') : '—'}
                      </td>
                      <td>{item.max_depth ?? item.depth ?? '—'}</td>
                      <td>
                        <span className={scoreBadgeClass(item.confidence)}>
                          {item.confidence ?? 0}
                        </span>
                      </td>
                    </tr>
                  ))}

                  {!fraudCycles.length && (
                    <tr>
                      <td colSpan="5">
                        <div className="empty-state">
                          No circular loops detected yet.
                        </div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <div
            style={{
              overflow: 'hidden',
              borderRadius: 22,
              background: 'linear-gradient(180deg, rgba(8,26,17,0.92), rgba(0,0,0,0.96))',
              border: '1px solid rgba(91,255,145,0.10)',
              boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.02), 0 14px 40px rgba(0,0,0,0.35)',
            }}
          >
            <div
              style={{
                padding: '18px 20px',
                borderBottom: '1px solid rgba(255,255,255,0.05)',
              }}
            >
              <div style={{ fontSize: 18, fontWeight: 900, color: '#ebfff0' }}>
                Risk Log
              </div>
              <div style={{ color: '#71877b', fontSize: 13, marginTop: 6 }}>
                Abnormal price, repeated-trading, and trust-based suspicious events
              </div>
            </div>

            <div className="scroll-y" style={{ maxHeight: 560 }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Trade ID</th>
                    <th>Risk Score</th>
                    <th>Label</th>
                    <th>Reason</th>
                    <th>Detected</th>
                  </tr>
                </thead>
                <tbody>
                  {riskLogs.map((log, idx) => (
                    <tr key={`${log.risk_id || log.trade_id}-${idx}`}>
                      <td>#{log.trade_id}</td>
                      <td>{log.risk_score}</td>
                      <td>
                        <span className={badgeClass(log.risk_score)}>
                          {log.risk_label || 'SUSPICIOUS'}
                        </span>
                      </td>
                      <td style={{ maxWidth: 520 }}>{log.reason}</td>
                      <td>{formatTime(log.detected_at)}</td>
                    </tr>
                  ))}

                  {!riskLogs.length && (
                    <tr>
                      <td colSpan="5">
                        <div className="empty-state">No risk logs yet.</div>
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
